#include <span>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    // Hexi's buffer_adaptor requires a mutable buffer type because it supports both reading and writing.
    // Since we are only reading, we can safely const_cast the data pointer.
    std::span<uint8_t> mut_buf(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::buffer_adaptor<std::span<uint8_t>> adaptor(mut_buf);
    hexi::binary_stream stream(adaptor);

    NetworkPacket packet;

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using the length prefix
    stream >> hexi::prefixed(packet.username);

    // Read the score count, then use read_container to read the scores vector
    // (hexi::prefixed internally reads the count and calls read_container)
    stream >> hexi::prefixed(packet.scores);

    // Read the metadata string as null-terminated for zero-copy
    // We read into a string_view first to avoid intermediate allocations, then assign to the string
    std::string_view metadata_view;
    stream >> hexi::null_terminated(metadata_view);
    packet.metadata = metadata_view;

    // Skip any remaining padding bytes (if any)
    if (stream.read_max() > 0) {
        stream.skip(stream.read_max());
    }

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    std::span<uint8_t> mut_buf(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::buffer_adaptor<std::span<uint8_t>> adaptor(mut_buf);
    hexi::binary_stream stream(adaptor);

    PacketInfo info{};

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto id_span = stream.span<const uint32_t>(1);
    if (!id_span.empty()) {
        info.packet_id = id_span[0];
    }

    // Read username using prefixed adaptor to get a string_view
    stream >> hexi::prefixed(info.username);

    // Skip the scores vector without reading its elements (read count, then skip the data)
    uint32_t scores_count = 0;
    stream >> hexi::endian::le(scores_count);
    stream.skip(scores_count * sizeof(uint32_t));

    return info;
}
