std::vector<uint32_t> read_item_batch(const std::span<const uint8_t> buffer) {
    // Create a non-const span so it can be bound to the buffer_adaptor's reference
    std::span<const uint8_t> buf = buffer;

    // Wrap the span in a buffer_adaptor
    hexi::buffer_adaptor<std::span<const uint8_t>> ba(buf);

    // Create the binary stream for reading
    hexi::binary_stream stream(ba);

    std::vector<uint32_t> items;

    // hexi::prefixed reads a uint32_t count and then internally calls 
    // read_container to read all the items into the vector.
    stream >> hexi::prefixed(items);

    return items;
