DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    if (buffer.empty()) {
        return result;
    }

    // Cast away constness to satisfy buffer_adaptor's underlying requirements.
    // This is safe because we will only perform read operations.
    std::span<uint8_t> mut_buffer(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::buffer_adaptor<std::span<uint8_t>> adaptor(mut_buffer);

    // Ensure there is at least enough data to read the data_type
    if (adaptor.size() < sizeof(uint8_t)) {
        return result;
    }

    // Preview the first byte (data_type) without advancing the read pointer
    uint8_t preview_type;
    adaptor.copy(&preview_type);

    // Check available data size for the full header (data_type + item_count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result;
    }

    // Initialize the binary stream for reading
    hexi::binary_stream stream(adaptor);

    uint8_t read_type;
    uint32_t item_count;

    // Read the header (this will advance the read pointer)
    stream >> read_type >> item_count;

    if (!stream.good()) {
        return result;
    }

    // Validate the data type
    if (read_type != 0 && read_type != 1) {
        return result;
    }

    result.data_type = read_type;

    // Check available data size for the items to prevent buffer underruns or overflow
    size_t item_size = (read_type == 0) ? sizeof(uint32_t) : sizeof(float);
    if (item_count > stream.read_max() / item_size) {
        return result;
    }

    // Read the items based on the data type
    if (read_type == 0) {
        result.int_items.resize(item_count);
        stream.get(result.int_items);
    } else if (read_type == 1) {
        result.float_items.resize(item_count);
        stream.get(result.float_items);
    }

    return result;
}
