	 */
	binary_stream_writer& operator<<(const char* data) {
		assert(data);
		const auto len = std::strlen(data);
		write(data, len + 1); // include terminator
		return *this;
	}

	binary_stream_writer& operator<<(const is_iterable auto& data) {
		write_container(data);
		return *this;
	}

	/**
