	std::size_t total_write() const {
		return total_write_;
	}

	/** 
	 * @brief Get a pointer to the buffer write interface.
	 *
	 * @return Pointer to the buffer write interface. 
	 */
	buffer_write* buffer() {
		return &buffer_;
	}

	/** 
	 * @brief Get a pointer to the buffer write interface.
	 *
	 * @return Pointer to the buffer write interface. 
	 */
	const buffer_write* buffer() const {
		return &buffer_;
	}
};

