#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create a buffer adaptor for the vector
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer);

    // Clear the adaptor to reset the write pointer to the beginning, 
    // making the entire pre-allocated buffer size available.
    adaptor.clear();

    // Calculate the required space for the header and the items
    size_t required_space = sizeof(header) + (items.size() * sizeof(uint32_t));

    // Check available space using the adaptor
    if (adaptor.free() < required_space) {
        return false;
    }

    // Get the write pointer (as requested)
    auto* write_ptr = adaptor.write_ptr();
    (void)write_ptr; // Suppress unused variable warning

    // Initialize the binary stream with the adaptor
    hexi::binary_stream<hexi::buffer_adaptor<std::vector<uint8_t>>> stream(adaptor);

    // Write the header
    stream << header;

    // Write the container data (this internally uses write_container)
    stream << items;

    // Return true if the write was successful and the stream is in a good state
    return stream.good();
}
