#include <hexi/hexi.h>
#include <cstdint>
#include <span>
#include <string_view>

struct MessagePacket {
    uint32_t header;
    std::string_view message;
};

MessagePacket read_header_and_message(const std::span<const uint8_t> buffer) {
    // Create a local copy of the span so the adaptor can reference it
    auto local_buffer = buffer;

    // Initialize buffer_adaptor with the buffer
    hexi::buffer_adaptor adaptor(local_buffer);

    MessagePacket packet{};

    // Use buffer_adaptor's read method to read the header
    // This reads sizeof(uint32_t) bytes directly from the buffer
    adaptor.read(&packet.header);

    // Initialize binary_stream with the adaptor
    // The stream picks up at the current read position of the adaptor
    hexi::binary_stream stream(adaptor);

    // Use binary_stream's view method to read the null-terminated message
    // This returns a string_view and advances the stream past the null terminator
    packet.message = stream.view();

    return packet;
}
