		  buffer_(source),
		  total_read_(0),
		  read_limit_(read_limit) {}

	binary_stream_reader(binary_stream_reader&& rhs) noexcept
		: stream_base(rhs),
		  buffer_(rhs.buffer_),
		  total_read_(rhs.total_read_),
		  read_limit_(rhs.read_limit_) {
