	std::size_t total_write_;

	inline void write(const void* data, const std::size_t size) {
		HEXI_TRY {
			if(state() == stream_state::ok) [[likely]] {
				buffer_.write(data, size);
				total_write_ += size;
			}
		} HEXI_CATCH(...) {
			set_state(stream_state::buff_write_err);

			if(allow_throw()) {
