std::vector<uint8_t> preview_file_header(const std::filesystem::path& file_path, size_t header_size) {
    // Open the file using Hexi's file_buffer
    hexi::file_buffer buffer(file_path);

    // Check if the file was opened successfully
    if (buffer.error()) {
        return {};
    }

    // Ensure we don't try to read more bytes than the file actually contains
    // This prevents the buffer_underrun exception from being thrown by copy()
    size_t actual_size = std::min(header_size, buffer.size());

    std::vector<uint8_t> header(actual_size);

    if (actual_size > 0) {
        // The copy() method reads data into the destination buffer 
        // without advancing the internal read cursor.
        buffer.copy(header.data(), actual_size);
    }

    // Check if any error occurred during the copy operation
    if (buffer.error()) {
        return {};
    }

    return header;
}
