	 * it to be used for streaming operations again. Has no effect
	 * if the stream has not errored.
	 */
	void clear_state() {
		state_ = stream_state::ok;
	}

	operator bool() const {
		return good();
	}

	/**
	 * @brief Set the stream to an error state.
