std::vector<uint8_t> serialize_with_padding(const PaddedData& packet) {
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor initialized as empty to write into the vector
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Create a binary stream using the adaptor
    hexi::binary_stream stream(adaptor);

    // Write header
    stream << packet.header;

    // Write data (Hexi automatically prefixes std::string with its length)
    stream << packet.data;

    // Write 16 bytes of padding (0x00)
    stream.fill<16>(0x00);

    // Write footer
    stream << packet.footer;

    return buffer;
}
