    writer.write(input_data.data(), input_data.size());

    // Then use buffer_read_adaptor to read it back
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer);

    // Use size() to check the readable size
    std::size_t readable_size = reader.size();
    std::vector<uint8_t> output_data(readable_size);

