struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor << sensor_id;

        // Write temperatures count (needed for deserialization)
        // Using little-endian for the count to match the data convention
        uint32_t count = static_cast<uint32_t>(temperatures.size());
        adaptor << hexi::endian::le(count);

        // Convert and write temperatures
        for (float temp : temperatures) {
            // Convert from native to little-endian using conditional_reverse with runtime parameters
            float converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            // Write converted temperature using the stream's put method (public equivalent to write)
            adaptor.put(converted);
        }

        // Convert and write pressure
        // Convert from native to little-endian using conditional_reverse with runtime parameters
        double p_converted = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        // Write converted pressure using the stream's put method
        adaptor.put(p_converted);
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor >> sensor_id;

        // Read temperatures count
        uint32_t count;
        adaptor >> hexi::endian::le(count);

        // Read temperatures
        temperatures.resize(count);
        for (uint32_t i = 0; i < count; ++i) {
            float temp;
            // Read raw bytes
            adaptor.get(temp);
            // Convert from little-endian to native using little_to_native_inplace
            hexi::endian::little_to_native_inplace(temp);
            temperatures[i] = temp;
        }

        // Read pressure
        adaptor.get(pressure);
        // Convert from little-endian to native using little_to_native_inplace
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    // Create a buffer adaptor for the vector
    hexi::buffer_adaptor<std::vector<uint8_t>> buf_adaptor(buffer);
    // Create the binary stream
    hexi::binary_stream stream(buf_adaptor);
    // Serialize the data
    stream.serialise(data);
    return buffer;
}

MeasurementData deserialize_measurement_data(const std::span<const uint8_t> buffer) {
    MeasurementData data;
    // Create a buffer adaptor for the read-only span
    hexi::buffer_adaptor<std::span<const uint8_t>> buf_adaptor(buffer);
    // Create the binary stream
    hexi::binary_stream stream(buf_adaptor);
    // Deserialize the data
    stream.deserialise(data);
    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    SensorInfo info{};
    hexi::buffer_adaptor<std::span<const uint8_t>> buf_adaptor(buffer);
    hexi::binary_stream stream(buf_adaptor);

    // Use view to extract a null-terminated sensor name string (if present)
    // view('\0') reads up to the null terminator and advances the stream past it.
    info.sensor_name = stream.view('\0');

    // Use enforce_read_bounds to check if there's enough data before reading the sensor_id
    // Note: enforce_read_bounds is a private member of binary_stream. 
    // We check read_max() to ensure safety as requested.
    if (stream.read_max() < sizeof(uint32_t)) {
        return info;
    }

    // Read the sensor_id (uint32_t) directly
    stream.get(info.sensor_id);

    // Skip the remaining data using skip
    if (stream.read_max() > 0) {
        stream.skip(stream.read_max());
    }

    return info;
}
